    #[test]
    fn validates_exact_recursive_scalar_source_spans_and_rejects_forgery() {
        const SQL: &str = "SELECT EXP(AVG(x)) FROM t";
        let valid = scalar_binding_test_rel(scalar_binding_test_rex(), SQL);
        validate_scalar_source_bindings(&valid, Some(SQL), None).unwrap();

        let mut partial_rex = scalar_binding_test_rex();
        partial_rex.as_object_mut().unwrap().remove("sourceText");
        let partial = scalar_binding_test_rel(partial_rex, SQL);
        assert!(validate_scalar_source_bindings(&partial, Some(SQL), None).is_err());

        let mut forged_text_rex = scalar_binding_test_rex();
        forged_text_rex["sourceText"] = serde_json::json!("EXP(AVG(y))");
        let forged_text = scalar_binding_test_rel(forged_text_rex, SQL);
        assert!(validate_scalar_source_bindings(&forged_text, Some(SQL), None).is_err());

        let mut escaped_child_rex = scalar_binding_test_rex();
        let escaped = &mut escaped_child_rex["operands"][0]["operands"][0];
        escaped["sourceSql"] = serde_json::json!("t");
        escaped["sourceNodeId"] = serde_json::json!("1:25-1:25");
        escaped["sourceText"] = serde_json::json!("t");
        let escaped_child = scalar_binding_test_rel(escaped_child_rex, SQL);
        assert!(validate_scalar_source_bindings(&escaped_child, Some(SQL), None).is_err());
    }

