    fn projected_expansion_fixture(
        duplicate_output_alias: bool,
    ) -> (String, CalciteRex, SourceSpan) {
        fn span_id(source: &str, start: usize, end: usize) -> String {
            assert!(start < end && end <= source.len());
            let start_column = source[..start].chars().count() + 1;
            let end_column = source[..end].chars().count();
            format!("1:{start_column}-1:{end_column}")
        }

        let second_item = if duplicate_output_alias {
            "c AS volume"
        } else {
            "c AS other"
        };
        let source = format!(
            "SELECT CASE WHEN flag THEN volume ELSE 0 END FROM \
             (SELECT a * b AS volume, {second_item} FROM t) AS d"
        );
        let case_text = "CASE WHEN flag THEN volume ELSE 0 END";
        let case_start = source.find(case_text).unwrap();
        let case_end = case_start + case_text.len();
        let flag_start = case_start + case_text.find("flag").unwrap();
        let reference_start = case_start + case_text.find("volume").unwrap();
        let zero_start = case_start + case_text.rfind('0').unwrap();
        let inner_text = format!("SELECT a * b AS volume, {second_item} FROM t");
        let inner_start = source.find(&inner_text).unwrap();
        let inner_end = inner_start + inner_text.len();
        let project_item_text = "a * b AS volume";
        let project_item_start = source.find(project_item_text).unwrap();
        let project_item_end = project_item_start + project_item_text.len();
        let definition_text = "a * b";
        let definition_start = source.find(definition_text).unwrap();
        let definition_end = definition_start + definition_text.len();
        let output_alias_start = project_item_start + project_item_text.rfind("volume").unwrap();
        let output_alias_end = output_alias_start + "volume".len();
        let a_start = definition_start;
        let b_start = definition_start + definition_text.rfind('b').unwrap();

        let node_id = |start, end| span_id(&source, start, end);
        let expansion = serde_json::json!({
            "kind": "DIRECT_DERIVED_OUTPUT_ALIAS",
            "referenceNodeId": node_id(reference_start, reference_start + 6),
            "referenceText": "volume",
            "definitionNodeId": node_id(definition_start, definition_end),
            "definitionText": definition_text,
            "projectItemNodeId": node_id(project_item_start, project_item_end),
            "projectItemText": project_item_text,
            "outputAliasNodeId": node_id(output_alias_start, output_alias_end),
            "outputAliasText": "volume",
            "innerSelectNodeId": node_id(inner_start, inner_end),
            "innerSelectText": inner_text,
            "outerFromNodeId": node_id(inner_start, source.len()),
            "outerFromText": &source[inner_start..],
            "outerSelectNodeId": node_id(0, source.len()),
            "outerSelectText": source
        });
        let left = serde_json::json!({
            "kind": "INPUT_REF",
            "class": "RexInputRef",
            "text": "$1",
            "type": "INTEGER",
            "index": 1,
            "sourceSql": "a",
            "sourceNodeId": node_id(a_start, a_start + 1),
            "sourceText": "a",
            "sourceKind": "IDENTIFIER"
        });
        let right = serde_json::json!({
            "kind": "INPUT_REF",
            "class": "RexInputRef",
            "text": "$2",
            "type": "INTEGER",
            "index": 2,
            "sourceSql": "b",
            "sourceNodeId": node_id(b_start, b_start + 1),
            "sourceText": "b",
            "sourceKind": "IDENTIFIER"
        });
        let expanded = serde_json::json!({
            "kind": "TIMES",
            "class": "RexCall",
            "text": "*($1, $2)",
            "type": "INTEGER",
            "operator": "*",
            "opKind": "TIMES",
            "sourceSql": definition_text,
            "sourceNodeId": node_id(definition_start, definition_end),
            "sourceText": definition_text,
            "sourceKind": "TIMES",
            "sourceOperator": "*",
            "sourceExpansion": expansion,
            "operands": [left, right]
        });
        let condition = serde_json::json!({
            "kind": "INPUT_REF",
            "class": "RexInputRef",
            "text": "$0",
            "type": "BOOLEAN",
            "index": 0,
            "sourceSql": "flag",
            "sourceNodeId": node_id(flag_start, flag_start + 4),
            "sourceText": "flag",
            "sourceKind": "IDENTIFIER"
        });
        let fallback = serde_json::json!({
            "kind": "LITERAL",
            "class": "RexLiteral",
            "text": "0",
            "type": "INTEGER",
            "sourceSql": "0",
            "sourceNodeId": node_id(zero_start, zero_start + 1),
            "sourceText": "0",
            "sourceKind": "LITERAL"
        });
        let parent: CalciteRex = serde_json::from_value(serde_json::json!({
            "kind": "CASE",
            "class": "RexCall",
            "text": "CASE($0, *($1, $2), 0)",
            "type": "INTEGER",
            "operator": "CASE",
            "opKind": "CASE",
            "sourceSql": case_text,
            "sourceNodeId": node_id(case_start, case_end),
            "sourceText": case_text,
            "sourceKind": "CASE",
            "sourceOperator": "CASE",
            "operands": [condition, expanded, fallback]
        }))
        .unwrap();
        let parent_span = parse_source_span_id(parent.source_node_id.as_deref().unwrap()).unwrap();
        (source, parent, parent_span)
    }

    #[test]
    fn validates_direct_derived_alias_expansion_and_rejects_coherent_forgery() {
        let (source, parent, parent_span) = projected_expansion_fixture(false);
        let child = &parent.operands[1];
        let expansion = child.source_expansion.as_ref().unwrap();
        validate_projected_source_expansion(
            child,
            expansion,
            Some(&source),
            Some(parent_span),
            Some(&parent),
            Some(1),
            "fixture",
        )
        .unwrap();

        let mut alias_mismatch_parent = parent.clone();
        let exact_flag = &alias_mismatch_parent.operands[0];
        let flag_node_id = exact_flag.source_node_id.clone().unwrap();
        let flag_text = exact_flag.source_text.clone().unwrap();
        let alias_mismatch = alias_mismatch_parent.operands[1]
            .source_expansion
            .as_mut()
            .unwrap();
        alias_mismatch.reference_node_id = flag_node_id;
        alias_mismatch.reference_text = flag_text;
        let child = &alias_mismatch_parent.operands[1];
        assert!(
            validate_projected_source_expansion(
                child,
                child.source_expansion.as_ref().unwrap(),
                Some(&source),
                Some(parent_span),
                Some(&alias_mismatch_parent),
                Some(1),
                "alias-mismatch",
            )
            .is_err()
        );

        let mut swapped_parent = parent.clone();
        let swapped_child = &mut swapped_parent.operands[1];
        let swapped = swapped_child.source_expansion.as_mut().unwrap();
        std::mem::swap(
            &mut swapped.definition_node_id,
            &mut swapped.project_item_node_id,
        );
        std::mem::swap(&mut swapped.definition_text, &mut swapped.project_item_text);
        swapped_child.source_node_id = Some(swapped.definition_node_id.clone());
        swapped_child.source_text = Some(swapped.definition_text.clone());
        swapped_child.source_sql = Some(swapped.definition_text.clone());
        let child = &swapped_parent.operands[1];
        assert!(
            validate_projected_source_expansion(
                child,
                child.source_expansion.as_ref().unwrap(),
                Some(&source),
                Some(parent_span),
                Some(&swapped_parent),
                Some(1),
                "coherent-swap",
            )
            .is_err()
        );

        let mut generated_mismatch_parent = parent.clone();
        let generated_mismatch = &mut generated_mismatch_parent.operands[1];
        generated_mismatch.source_kind = Some("IDENTIFIER".to_owned());
        generated_mismatch.source_operator = None;
        let child = &generated_mismatch_parent.operands[1];
        assert!(
            validate_projected_source_expansion(
                child,
                child.source_expansion.as_ref().unwrap(),
                Some(&source),
                Some(parent_span),
                Some(&generated_mismatch_parent),
                Some(1),
                "generated-source-mismatch",
            )
            .is_err()
        );

        let (duplicate_source, duplicate_parent, duplicate_parent_span) =
            projected_expansion_fixture(true);
        let duplicate_child = &duplicate_parent.operands[1];
        assert!(
            validate_projected_source_expansion(
                duplicate_child,
                duplicate_child.source_expansion.as_ref().unwrap(),
                Some(&duplicate_source),
                Some(duplicate_parent_span),
                Some(&duplicate_parent),
                Some(1),
                "duplicate-output",
            )
            .is_err()
        );
    }

