    #[test]
    fn query_level_order_by_alias_error_marker_fails_closed_on_generic_or_malformed_data() {
        let pristine = order_by_alias_analysis_error_file();
        let mut cases = Vec::new();

        let mut unknown_kind = pristine.clone();
        unknown_kind.queries[0]
            .source_analysis_error
            .as_mut()
            .unwrap()
            .kind = "GENERIC_UNDEFINED_COLUMN".to_owned();
        cases.push(("unknown marker kind", unknown_kind));

        let mut wrong_state = pristine.clone();
        wrong_state.queries[0]
            .source_analysis_error
            .as_mut()
            .unwrap()
            .sql_state = "00000".to_owned();
        cases.push(("wrong SQLSTATE", wrong_state));

        let mut empty_identity = pristine.clone();
        empty_identity.queries[0]
            .source_analysis_error
            .as_mut()
            .unwrap()
            .source_order_item_node_id
            .clear();
        cases.push(("empty order-item identity", empty_identity));

        let mut mismatched_block = pristine.clone();
        mismatched_block.queries[0]
            .source_analysis_error
            .as_mut()
            .unwrap()
            .query_block_id = "other".to_owned();
        cases.push(("mismatched query block", mismatched_block));

        let mut stale_order_item = pristine.clone();
        stale_order_item.queries[0]
            .source_analysis_error
            .as_mut()
            .unwrap()
            .source_order_item_sql = "`alias` + 2".to_owned();
        cases.push(("stale source order item", stale_order_item));

        let mut stale_alias_span = pristine.clone();
        stale_alias_span.queries[0]
            .source_analysis_error
            .as_mut()
            .unwrap()
            .source_output_alias_node_id = "1:8-1:8".to_owned();
        cases.push(("stale output alias span", stale_alias_span));

        let mut changed_statement = pristine.clone();
        changed_statement.queries[0].sql =
            "SELECT x AS different_alias FROM t ORDER BY different_alias + 1".to_owned();
        cases.push(("changed independent statement", changed_statement));

        let mut missing_source = serde_json::to_value(&pristine).unwrap();
        missing_source["queries"][0]
            .as_object_mut()
            .unwrap()
            .remove("sql");
        assert!(serde_json::from_value::<CalciteFile>(missing_source).is_err());

        let mut blank_source = pristine;
        blank_source.queries[0].sql.clear();
        assert!(matches!(
            convert_raw_file(blank_source),
            Err(Error::CalciteQueryError(_))
        ));

        for (label, raw) in cases {
            assert!(
                matches!(
                    convert_raw_file(raw),
                    Err(Error::InvalidRelSourceProvenance(_))
                ),
                "{label} must fail closed"
            );
        }
    }

