    #[test]
    fn source_grouping_parent_clause_flags_are_mandatory_and_lexical() {
        let mut marker = serde_json::json!({
            "kind": "ROLLUP",
            "queryBlockId": "q1",
            "sourceSelectNodeId": "q1",
            "sourceSelectText": "SELECT `a` FROM `t` GROUP BY ROLLUP(`a`)",
            "sourceSelectSql": "SELECT `a` FROM `t` GROUP BY ROLLUP(`a`)",
            "sourceGroupNodeId": "group1",
            "sourceGroupText": "ROLLUP(`a`)",
            "sourceGroupSql": "ROLLUP(`a`)",
            "groupIndexes": [0],
            "groupingSets": [[0], []]
        });
        assert!(
            serde_json::from_value::<CalciteSourceGroupingAttestation>(marker.clone()).is_err()
        );
        marker["sourceHasWhere"] = serde_json::json!(false);
        assert!(
            serde_json::from_value::<CalciteSourceGroupingAttestation>(marker.clone()).is_err()
        );
        marker["sourceHasHaving"] = serde_json::json!(false);
        assert!(serde_json::from_value::<CalciteSourceGroupingAttestation>(marker).is_ok());

        assert_eq!(
            source_select_top_level_clause_flags(
                "/* WHERE */ SELECT `where`, 'HAVING', $$ WHERE $$ FROM \
                 (SELECT 1 WHERE TRUE HAVING TRUE) AS `having`"
            ),
            Some((false, false))
        );
        assert_eq!(
            source_select_top_level_clause_flags(
                "SELECT `a` FROM `t` WHERE `a` > 0 GROUP BY ROLLUP(`a`) HAVING COUNT(*) > 0"
            ),
            Some((true, true))
        );
        assert_eq!(
            source_select_top_level_clause_flags("SELECT `a` FROM (SELECT 1 WHERE TRUE"),
            None
        );
    }

    #[test]
    fn shared_source_lexer_projections_hide_protected_structure_without_broadening_identity() {
        assert_eq!(
            lexical_sql_tokens("SELECT /* outer /* JOIN */ ORDER BY */ \"a\"\"b\"").unwrap(),
            ["identifier:select", "identifier:a\"b"]
        );
        assert!(!lexical_sql_equal("E'x'", "'x'"));
        assert!(!lexical_sql_equal("$$x$$", "'x'"));

        let tokens = source_structure_tokens("SELECT 'FROM, ORDER BY' FROM t").unwrap();
        assert_eq!(
            tokens
                .iter()
                .filter_map(source_structure_word)
                .collect::<Vec<_>>(),
            ["select", "from", "t"]
        );
        assert!(source_structure_tokens("SELECT E'x'").is_none());
        assert!(source_structure_tokens("SELECT $$x$$").is_none());
    }

