    #[test]
    fn converts_basic_project_filter_scan() {
        let mut raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [{"name": "r", "columns": [{"name": "a", "type": "INTEGER"}]}],
              "queries": [{
                "sql": "select a from R where a = 1",
                "rel": {
                  "type": "LogicalProject",
                  "rowType": [{"name": "a", "type": "INTEGER", "nullable": true}],
                  "projectRex": [
                    {"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "INTEGER", "index": 0}
                  ],
                  "inputs": [{
                    "type": "LogicalFilter",
                    "rowType": [{"name": "a", "type": "INTEGER", "nullable": true}],
                    "conditionRex": {
                      "kind": "EQUALS",
                      "class": "RexCall",
                      "text": "=($0, 1)",
                      "type": "BOOLEAN",
                      "operator": "=",
                      "opKind": "EQUALS",
                      "operands": [
                        {"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "INTEGER", "index": 0},
                        {"kind": "LITERAL", "class": "RexLiteral", "text": "1", "type": "INTEGER", "sourceSql": "1", "sourceNodeId": "1:27-1:27", "sourceText": "1", "sourceKind": "LITERAL", "literalTypeName": "INTEGER", "literalValue": "1", "literalValue2": "1"}
                      ]
                    },
                    "inputs": [{
                      "type": "LogicalTableScan",
                      "rowType": [{"name": "a", "type": "INTEGER", "nullable": true}],
                      "table": ["r"],
                      "sourceTable": {
                        "kind": "DIRECT_BASE_TABLE",
                        "queryBlockId": "1:1-1:27",
                        "relationNodeId": "1:15-1:15",
                        "relationText": "R",
                        "tableNodeId": "1:15-1:15",
                        "tableText": "R",
                        "tableNames": ["r"],
                        "tableQuoted": [false],
                        "aliasNodeId": null,
                        "aliasText": null,
                        "aliasNames": [],
                        "aliasQuoted": []
                      },
                      "inputs": []
                    }]
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();

        {
            let source_sql = raw.queries[0].sql.clone();
            let project = raw.queries[0].rel.as_mut().unwrap();
            project.source_sql = Some(source_sql);
            project.source_kind = Some("SELECT".to_owned());
            project.source_operator = Some("SELECT".to_owned());
            let rex = &mut project.project_rex[0];
            rex.nullable = true;
            rex.source_sql = Some("a".to_owned());
            rex.source_kind = Some("IDENTIFIER".to_owned());
            rex.source_identifier_names = vec!["a".to_owned()];
            rex.source_identifier_quoted = vec![false];
        }
        bind_test_file_to_statements(&mut raw);

        let ir = convert_raw_file(raw).unwrap();
        assert_eq!(ir.schema.tables[0].name, "r");
        assert_eq!(ir.queries.len(), 1);
        assert!(ir.queries[0].analysis_errors.is_empty());
    }

    #[test]
    fn rejects_observable_cast_collapsed_to_input_ref() {
        for (target, ty) in [
            ("VARCHAR(65)", "VARCHAR"),
            ("CHAR(8)", "CHAR"),
            ("TIME(0)", "TIME"),
            ("TIMESTAMP(3)", "TIMESTAMP"),
            ("TIMESTAMP(2) WITHOUT TIME ZONE", "TIMESTAMP"),
        ] {
            let rex: CalciteRex = with_exact_test_rex(
                serde_json::from_value(serde_json::json!({
                    "kind": "INPUT_REF",
                    "class": "RexInputRef",
                    "text": "$0",
                    "type": ty,
                    "index": 0,
                    "sourceSql": format!("CAST(`t`.`x` AS {target})")
                }))
                .unwrap(),
            );

            let error = reject_collapsed_observable_cast(&rex, None).unwrap_err();
            assert!(
                error
                    .to_string()
                    .contains("no non-literal identity is authoritative")
            );
        }
    }

