    fn exact_folded_null_equals_one(source: &str) -> CalciteRex {
        with_exact_test_rex(
            serde_json::from_value(serde_json::json!({
                "kind": "LITERAL",
                "class": "RexLiteral",
                "text": "false",
                "type": "BOOLEAN",
                "nullable": false,
                "fullType": "BOOLEAN NOT NULL",
                "precision": 1,
                "scale": i32::MIN,
                "sourceSql": source,
                "sourceKind": "EQUALS",
                "sourceOperator": "=",
                "literalTypeName": "BOOLEAN",
                "literalValue": "false",
                "literalValue2": "false"
            }))
            .unwrap(),
        )
    }

    #[test]
    fn folded_null_integer_equality_is_reconstructed_not_booleanized() {
        for (source, null_first) in [("NULL = 1", true), ("0001 = NULL", false)] {
            let rex = exact_folded_null_equals_one(source);
            let ast = calcite_rex_ast(&rex, &BTreeMap::new()).unwrap();
            let ScalarAst::Call {
                op: ScalarOp::Eq,
                args,
                ..
            } = ast
            else {
                panic!("folded {source:?} was not reconstructed as equality")
            };
            let typed_raw = |ast: &ScalarAst| match ast {
                ScalarAst::TypeAnnotation { expr, ty }
                    if ty == "INTEGER" && matches!(expr.as_ref(), ScalarAst::Literal { .. }) =>
                {
                    let ScalarAst::Literal { raw } = expr.as_ref() else {
                        unreachable!()
                    };
                    raw.clone()
                }
                _ => panic!("folded equality operand is not an INTEGER literal: {ast:?}"),
            };
            assert_eq!(typed_raw(&args[usize::from(!null_first)]), "NULL");
            assert_eq!(typed_raw(&args[usize::from(null_first)]), "1");
        }

        let pristine = exact_folded_null_equals_one("NULL = 1");
        let mut rendered_drift = pristine.clone();
        rendered_drift.source_sql = Some("forged rendered diagnostic".to_owned());
        assert!(exact_folded_null_integer_equality_ast(&rendered_drift).is_some());
        let mut forged = Vec::new();

        let mut true_payload = pristine.clone();
        true_payload.text = Some("true".to_owned());
        true_payload.literal_value = Some("true".to_owned());
        true_payload.literal_value2 = Some("true".to_owned());
        forged.push(("TRUE payload", true_payload));

        let mut identifier = pristine.clone();
        identifier.source_text = Some("x = NULL".to_owned());
        forged.push(("nonliteral operand", identifier));

        let mut trailing = pristine.clone();
        trailing.source_text = Some("NULL = 1 OR true".to_owned());
        forged.push(("trailing tokens", trailing));

        let mut operator = pristine.clone();
        operator.source_text = Some("NULL <> 1".to_owned());
        operator.source_kind = Some("NOT_EQUALS".to_owned());
        operator.source_operator = Some("<>".to_owned());
        forged.push(("operator", operator));

        let mut result_type = pristine.clone();
        result_type.ty = Some("INTEGER".to_owned());
        result_type.full_type = Some("INTEGER NOT NULL".to_owned());
        result_type.precision = Some(10);
        result_type.scale = Some(0);
        forged.push(("result type", result_type));

        let mut family = pristine.clone();
        family.literal_type_name = Some("INTEGER".to_owned());
        forged.push(("literal family", family));

        let mut decimal = pristine.clone();
        decimal.source_text = Some("NULL = 1.0".to_owned());
        forged.push(("non-integral literal", decimal));

        let mut bigint = pristine.clone();
        bigint.source_text = Some("NULL = 2147483648".to_owned());
        forged.push(("non-int4 literal", bigint));

        let mut two_nulls = pristine.clone();
        two_nulls.source_text = Some("NULL = NULL".to_owned());
        forged.push(("two NULL operands", two_nulls));

        for (label, forged_rex) in forged {
            assert!(
                exact_folded_null_integer_equality_ast(&forged_rex).is_none(),
                "forged {label} passed folded-equality reconstruction"
            );
            assert!(
                calcite_rex_ast(&forged_rex, &BTreeMap::new()).is_err(),
                "forged {label} was accepted by a generic literal path"
            );
        }
    }

    #[test]
    fn unresolved_values_null_requires_exact_bare_source_and_payload_views() {
        let rex: CalciteRex = with_exact_test_rex(
            serde_json::from_value(serde_json::json!({
                "kind": "LITERAL",
                "class": "RexLiteral",
                "text": "null:NULL",
                "type": "NULL",
                "nullable": true,
                "fullType": "NULL",
                "precision": -1,
                "scale": i32::MIN,
                "sourceSql": "NULL",
                "sourceKind": "LITERAL",
                "literalTypeName": "NULL",
                "literalValue": "null",
                "literalValue2": "null"
            }))
            .unwrap(),
        );
        assert!(exact_unresolved_bare_null_literal(&rex));
        assert_eq!(
            calcite_rex_literal_ast(&rex).unwrap(),
            ScalarAst::Literal {
                raw: "NULL".to_owned()
            }
        );

        for (label, forged) in [
            ("source expression", {
                let mut value = rex.clone();
                value.source_text = Some("NULLIF(1, 1)".to_owned());
                value
            }),
            ("payload", {
                let mut value = rex.clone();
                value.literal_value2 = Some("0".to_owned());
                value
            }),
            ("generated operand", {
                let mut value = rex.clone();
                value.operands.push(rex.clone());
                value
            }),
        ] {
            assert!(
                !exact_unresolved_bare_null_literal(&forged),
                "forged {label} passed unresolved-NULL validation"
            );
            assert!(calcite_rex_literal_ast(&forged).is_err(), "{label}");
        }

        let mut resolved = rex;
        resolved.ty = Some("BOOLEAN".to_owned());
        resolved.full_type = Some("BOOLEAN".to_owned());
        resolved.precision = Some(1);
        assert!(!exact_unresolved_bare_null_literal(&resolved));
        assert_eq!(
            calcite_rex_literal_ast(&resolved).unwrap(),
            ScalarAst::Literal {
                raw: "NULL".to_owned()
            }
        );
    }

    #[test]
    fn source_cast_detection_requires_cast_to_be_the_complete_root() {
        assert!(source_is_exact_top_level_cast(
            "CAST(t.x AS positive_int_domain)"
        ));
        assert!(source_is_exact_top_level_cast(
            "CAST((t.x + 1) AS NUMERIC(4, 2))"
        ));
        assert!(!source_is_exact_top_level_cast(
            "CAST(t.x AS NUMERIC) / CAST(t.y AS NUMERIC) < 0.9"
        ));
        assert!(!source_is_exact_top_level_cast("CAST(t.x AS NUMERIC) + 1"));
    }

