    #[test]
    fn rejects_calcite_folded_fractional_numeric_to_integer_literals() {
        for (source_value, folded_value) in [("1.9", "1"), ("-1.9", "-1")] {
            let rex: CalciteRex = with_exact_test_rex(
                serde_json::from_value(serde_json::json!({
                    "kind": "LITERAL",
                    "class": "RexLiteral",
                    "text": folded_value,
                    "type": "INTEGER",
                    "sourceSql": format!("CAST({source_value} AS INTEGER)"),
                    "sourceKind": "CAST",
                    "sourceOperator": "CAST",
                    "literalTypeName": "DECIMAL",
                    "literalValue": folded_value,
                    "literalValue2": folded_value
                }))
                .unwrap(),
            );

            validate_source_explicit_cast_target(&rex).unwrap();
            assert!(!collapsed_literal_cast_has_exact_source_reconstruction(
                &rex
            ));
            let error = calcite_rex_ast(&rex, &BTreeMap::new()).unwrap_err();
            assert!(
                error
                    .to_string()
                    .contains("Calcite's folded value is not semantic authority"),
                "{source_value}: {error}"
            );
        }

        let provenance_free_folded: CalciteRex = with_exact_test_rex(
            serde_json::from_value(serde_json::json!({
                "kind": "LITERAL",
                "class": "RexLiteral",
                "text": "1",
                "type": "INTEGER",
                "literalTypeName": "DECIMAL",
                "literalValue": "1",
                "literalValue2": "1"
            }))
            .unwrap(),
        );
        let error = calcite_rex_ast(&provenance_free_folded, &BTreeMap::new()).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("no independently parsed source SQL"),
            "{error}"
        );
    }

