    #[test]
    fn structured_rex_interval_preserves_sql_literal_unit_value() {
        let mut raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [
                {"name": "t", "columns": [
                  {"name": "d", "type": "DATE"},
                  {"name": "x", "type": "INTEGER"}
                ]}
              ],
              "queries": [{
                "sql": "select x from t where d < cast('1993-11-01' as date) + interval '30' day",
                "rel": {
                  "type": "LogicalFilter",
                  "rowType": [
                    {"name": "d", "type": "DATE", "nullable": true},
                    {"name": "x", "type": "INTEGER", "nullable": true}
                  ],
                  "conditionRex": {
                    "kind": "LESS_THAN",
                    "class": "RexCall",
                    "text": "<($0, +(CAST('1993-11-01'):DATE NOT NULL, 2592000000:INTERVAL DAY))",
                    "type": "BOOLEAN",
                    "operator": "<",
                    "opKind": "LESS_THAN",
                    "operands": [
                      {"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "DATE", "index": 0},
                      {
                        "kind": "PLUS",
                        "class": "RexCall",
                        "text": "+(CAST('1993-11-01'):DATE NOT NULL, 2592000000:INTERVAL DAY)",
                        "type": "DATE",
                        "operator": "+",
                        "opKind": "PLUS",
                        "operands": [
                          {
                            "kind": "CAST",
                            "class": "RexCall",
                            "text": "CAST('1993-11-01'):DATE NOT NULL",
                            "type": "DATE",
                            "sourceSql": "CAST('1993-11-01' AS DATE)",
                            "sourceKind": "CAST",
                            "operator": "CAST",
                            "opKind": "CAST",
                            "operands": [
                              {
                                "kind": "LITERAL",
                                "class": "RexLiteral",
                                "text": "'1993-11-01'",
                                "type": "CHAR",
                                "sourceSql": "'1993-11-01'",
                                "sourceKind": "LITERAL",
                                "literalTypeName": "CHAR",
                                "literalValueAsString": "1993-11-01",
                                "literalValue2": "1993-11-01"
                              }
                            ]
                          },
                          {
                            "kind": "LITERAL",
                            "class": "RexLiteral",
                            "text": "2592000000:INTERVAL DAY",
                            "type": "INTERVAL_DAY",
                            "nullable": false,
                            "fullType": "INTERVAL DAY NOT NULL",
                            "precision": 10,
                            "scale": 6,
                            "sourceSql": "INTERVAL '30' DAY",
                            "sourceKind": "LITERAL",
                            "literalTypeName": "INTERVAL_DAY",
                            "literalValue": "2592000000",
                            "literalValue2": "2592000000",
                            "literalValueAsString": "30",
                            "intervalTypeName": "INTERVAL_DAY",
                            "intervalLiteral": "30",
                            "intervalInternalValue": "2592000000",
                            "intervalUnit": "DAY"
                          }
                        ]
                      }
                    ]
                  },
                  "inputs": [{
                    "type": "LogicalTableScan",
                    "rowType": [
                      {"name": "d", "type": "DATE", "nullable": true},
                      {"name": "x", "type": "INTEGER", "nullable": true}
                    ],
                    "table": ["t"],
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();
        bind_test_file_to_statements(&mut raw);

        // This test isolates structured Rex-to-IR conversion. File-level
        // source/query-shape admission is covered by wrapper-backed tests.
        let rel = convert_current_wrapper_test_rel(
            raw.queries.into_iter().next().unwrap().rel.unwrap(),
            &BTreeMap::new(),
        )
        .unwrap();
        let RelExpr::Filter { predicate, .. } = &rel else {
            panic!("expected filter");
        };
        let ScalarAst::Call { args, .. } = &predicate.parsed else {
            panic!("expected parsed comparison");
        };
        let ScalarAst::Call {
            args: plus_args, ..
        } = &args[1]
        else {
            panic!("expected date addition");
        };
        let ScalarAst::TypeAnnotation { expr, ty } = &plus_args[1] else {
            panic!("expected interval annotation");
        };
        assert_eq!(ty, "INTERVAL DAY");
        assert_eq!(
            &**expr,
            &ScalarAst::Literal {
                raw: "30".to_owned()
            }
        );
    }

    fn exact_interval_literal_fixture(
        source: &str,
        type_name: &str,
        unit: &str,
        internal: &str,
        scale: i32,
    ) -> CalciteRex {
        with_exact_test_rex(
            serde_json::from_value(serde_json::json!({
                "kind": "LITERAL",
                "class": "RexLiteral",
                "text": format!("{internal}:{}", type_name.replace('_', " ")),
                "type": type_name,
                "nullable": false,
                "fullType": format!("{} NOT NULL", type_name.replace('_', " ")),
                "precision": 10,
                "scale": scale,
                "sourceSql": source,
                "sourceKind": "LITERAL",
                "literalTypeName": type_name,
                "literalValue": internal,
                "literalValue2": internal,
                "literalValueAsString": "1",
                "intervalTypeName": type_name,
                "intervalLiteral": "1",
                "intervalInternalValue": internal,
                "intervalUnit": unit
            }))
            .unwrap(),
        )
    }

    #[test]
    fn interval_literal_exact_source_closes_qualifier_type_unit_and_internal_value() {
        let day = exact_interval_literal_fixture(
            "INTERVAL '1' DAY",
            "INTERVAL_DAY",
            "DAY",
            "86400000",
            6,
        );
        validate_where_literal_source_binding(&day).unwrap();
        assert!(matches!(
            calcite_rex_literal_ast(&day).unwrap(),
            ScalarAst::TypeAnnotation { expr, ty }
                if ty == "INTERVAL DAY"
                    && matches!(expr.as_ref(), ScalarAst::Literal { raw } if raw == "1")
        ));

        let second = exact_interval_literal_fixture(
            "INTERVAL '1' SECOND(3)",
            "INTERVAL_SECOND",
            "SECOND",
            "1000",
            3,
        );
        validate_where_literal_source_binding(&second).unwrap();

        // Every generated view is coherently changed to HOUR, but the exact
        // original source remains DAY. Rendered sourceSql is diagnostic and
        // cannot bridge that mismatch.
        let mut coherent_hour_forgery = day.clone();
        coherent_hour_forgery.source_sql = Some("INTERVAL '1' HOUR".to_owned());
        coherent_hour_forgery.ty = Some("INTERVAL_HOUR".to_owned());
        coherent_hour_forgery.full_type = Some("INTERVAL HOUR NOT NULL".to_owned());
        coherent_hour_forgery.literal_type_name = Some("INTERVAL_HOUR".to_owned());
        coherent_hour_forgery.interval_type_name = Some("INTERVAL_HOUR".to_owned());
        coherent_hour_forgery.interval_unit = Some("HOUR".to_owned());
        coherent_hour_forgery.text = Some("3600000:INTERVAL HOUR".to_owned());
        coherent_hour_forgery.literal_value = Some("3600000".to_owned());
        coherent_hour_forgery.literal_value2 = Some("3600000".to_owned());
        coherent_hour_forgery.interval_internal_value = Some("3600000".to_owned());
        assert!(validate_where_literal_source_binding(&coherent_hour_forgery).is_err());
        assert!(calcite_rex_literal_ast(&coherent_hour_forgery).is_err());

        let mut trailing_junk = day.clone();
        trailing_junk.source_text = Some("INTERVAL '1' DAY trailing".to_owned());
        trailing_junk.source_node_id = Some(test_exact_span("INTERVAL '1' DAY trailing"));
        assert!(validate_where_literal_source_binding(&trailing_junk).is_err());
        assert!(calcite_rex_literal_ast(&trailing_junk).is_err());

        let mut wrong_internal = day;
        wrong_internal.literal_value = Some("3600000".to_owned());
        wrong_internal.literal_value2 = Some("3600000".to_owned());
        wrong_internal.interval_internal_value = Some("3600000".to_owned());
        wrong_internal.text = Some("3600000:INTERVAL DAY".to_owned());
        assert!(validate_where_literal_source_binding(&wrong_internal).is_err());

        for unsupported in [
            "INTERVAL '1 02:03:04' DAY TO SECOND(3)",
            "INTERVAL '1' YEAR TO DAY",
            "INTERVAL '1' DAY(2)",
            "INTERVAL '1' SECOND(7)",
        ] {
            assert!(
                parse_exact_postgres_interval_literal(unsupported).is_none(),
                "unsupported interval qualifier/payload must fail closed: {unsupported}"
            );
        }
    }

