    #[test]
    fn exact_sort_labels_cover_implicit_function_aliases_and_duplicate_names() {
        let query = "SELECT a, a, count(*) total_cnt FROM t";
        let query_span = parse_source_span_id(&format!("1:1-1:{}", query.len())).unwrap();
        let outputs = exact_sort_outputs_from_select(query_span, query, None).unwrap();
        assert_eq!(
            outputs
                .iter()
                .map(|output| output.name.as_deref())
                .collect::<Vec<_>>(),
            vec![Some("a"), Some("a"), Some("total_cnt")]
        );
        assert_eq!(
            calcite_uniquified_exact_output_names(&outputs).unwrap(),
            ["a", "a0", "total_cnt"]
        );

        let colliding = ["a", "a", "a0", "a"]
            .into_iter()
            .map(|name| ExactSortOutput {
                name: Some(name.to_owned()),
                definition: None,
                wildcard: false,
                wildcard_qualifier: None,
                qualifiers: BTreeSet::new(),
            })
            .collect::<Vec<_>>();
        assert_eq!(
            calcite_uniquified_exact_output_names(&colliding).unwrap(),
            ["a", "a0", "a00", "a1"]
        );

        assert!(direct_implicit_function_alias_ranges("a + b").is_none());
        assert!(direct_implicit_function_alias_ranges("count(*) + total_cnt").is_none());
        assert_eq!(
            direct_implicit_function_alias_ranges("count(*) \"total cnt\"").map(
                |(definition, alias)| (
                    &"count(*) \"total cnt\""[definition.0..definition.1],
                    &"count(*) \"total cnt\""[alias.0..alias.1],
                )
            ),
            Some(("count(*)", "\"total cnt\""))
        );
        assert!(
            direct_implicit_function_alias_ranges("count(*) FILTER (WHERE x) total_cnt").is_none()
        );
    }

    #[test]
    fn direct_simple_output_aliases_are_narrow_and_fail_closed() {
        fn split(source: &str) -> Option<(&str, &str)> {
            direct_implicit_simple_alias_ranges(source).map(|(definition, alias)| {
                (
                    &source[definition.0..definition.1],
                    &source[alias.0..alias.1],
                )
            })
        }
        assert_eq!(split("'store' channel"), Some(("'store'", "channel")));
        assert_eq!(
            split("s_store_name s_store_name1"),
            Some(("s_store_name", "s_store_name1"))
        );
        assert_eq!(
            split("CASE x WHEN 0 THEN NULL ELSE y END cov"),
            Some(("CASE x WHEN 0 THEN NULL ELSE y END", "cov"))
        );
        assert!(split("a + b").is_none());
        assert!(split("a AND b").is_none());
        assert!(split("CASE x WHEN 0 THEN y END").is_none());
    }

    #[test]
    fn cte_definition_lineage_does_not_reenter_the_same_local_cte_project() {
        let query = "SELECT base_col FROM base";
        let item = format!("x AS ({query})");
        let query_start = item.find(query).unwrap();
        let span = |start: usize, end: usize| format!("1:{}-1:{end}", start + 1);
        let query_id = span(query_start, query_start + query.len());
        let base_start = query_start + query.rfind("base").unwrap();
        let base_id = span(base_start, base_start + "base".len());
        let cte_use = crate::calcite::CalciteSourceCteUse {
            kind: "CTE_USE".to_owned(),
            relation_node_id: "1:1-1:1".to_owned(),
            relation_text: "x".to_owned(),
            reference_node_id: "1:1-1:1".to_owned(),
            reference_text: "x".to_owned(),
            definition_name_node_id: span(0, 1),
            definition_name_text: "x".to_owned(),
            definition_query_node_id: query_id.clone(),
            definition_query_text: query.to_owned(),
            definition_item_node_id: span(0, item.len()),
            definition_item_text: item.clone(),
            definition_list_node_id: span(0, item.len()),
            definition_list_text: item,
            definition_body_node_id: "1:1-1:1".to_owned(),
            definition_body_text: "x".to_owned(),
            definition_with_node_id: "1:1-1:1".to_owned(),
            definition_with_text: "x".to_owned(),
            reference_scope_kind: "WITH_BODY".to_owned(),
            reference_scope_node_id: "1:1-1:1".to_owned(),
            reference_scope_text: "x".to_owned(),
        };
        let mut project: CalciteRel = serde_json::from_value(serde_json::json!({
            "type": "LogicalProject",
            "rowType": [
                {"name": "hidden", "type": "INTEGER", "nullable": true},
                {"name": "base_col", "type": "INTEGER", "nullable": true}
            ],
            "projectRex": [
                {"class": "RexInputRef", "type": "INTEGER", "nullable": true, "index": 0},
                {"class": "RexInputRef", "type": "INTEGER", "nullable": true, "index": 1}
            ],
            "inputs": [{
                "type": "LogicalTableScan",
                "rowType": [
                    {"name": "hidden", "type": "INTEGER", "nullable": true},
                    {"name": "base_col", "type": "INTEGER", "nullable": true}
                ],
                "table": ["base"],
                "sourceTable": {
                    "kind": "DIRECT_BASE_TABLE",
                    "queryBlockId": query_id,
                    "relationOccurrenceId": base_id,
                    "relationNodeId": base_id,
                    "relationText": "base",
                    "tableNodeId": base_id,
                    "tableText": "base",
                    "tableNames": ["base"],
                    "tableQuoted": [false],
                    "aliasNodeId": null,
                    "aliasText": null,
                    "aliasNames": [],
                    "aliasQuoted": [],
                    "columnAliases": [],
                    "outputLineage": [{
                        "outputIndex": 0,
                        "kind": "BASE_COLUMN",
                        "relationOccurrenceId": base_id,
                        "baseColumnIndex": 0,
                        "baseColumnName": "hidden",
                        "visibleColumnName": "hidden",
                        "generatedFieldName": "hidden",
                        "explicitColumnAlias": false,
                        "columnAliasNodeId": null,
                        "columnAliasText": null
                    }, {
                        "outputIndex": 1,
                        "kind": "BASE_COLUMN",
                        "relationOccurrenceId": base_id,
                        "baseColumnIndex": 1,
                        "baseColumnName": "base_col",
                        "visibleColumnName": "base_col",
                        "generatedFieldName": "base_col",
                        "explicitColumnAlias": false,
                        "columnAliasNodeId": null,
                        "columnAliasText": null
                    }]
                }
            }]
        }))
        .unwrap();
        hydrate_current_wrapper_rel(&mut project);
        project.source_input_cte_uses = vec![Some(cte_use.clone())];

        // The public CTE has one column while this inlined Project still has
        // the base row. Resolving that output must descend through the exact
        // definition without re-entering this same local CTE edge.
        assert!(exact_cte_identifier_definition_resolves(
            &project,
            1,
            "x",
            &cte_use,
            &["base_col".to_owned()],
        ));
    }

