    #[test]
    fn logical_set_operation_requires_authoritative_set_op() {
        let raw: CalciteRel = serde_json::from_value(serde_json::json!({
            "type": "LogicalUnion",
            "rowType": [],
            "all": false,
            "inputs": []
        }))
        .unwrap();

        assert!(matches!(
            convert_rel(raw, &BTreeMap::new()),
            Err(Error::MissingField {
                node: "LogicalSetOp",
                field: "setOp"
            })
        ));
    }

    #[test]
    fn logical_set_operation_rejects_legacy_operator_aliases() {
        for (rel_type, legacy_set_op) in [
            ("LogicalUnion", "LogicalUnion"),
            ("LogicalIntersect", "LogicalIntersect"),
            ("LogicalMinus", "LogicalMinus"),
            ("LogicalMinus", "MINUS"),
        ] {
            let raw: CalciteRel = serde_json::from_value(serde_json::json!({
                "type": rel_type,
                "rowType": [],
                "setOp": legacy_set_op,
                "all": false,
                "inputs": []
            }))
            .unwrap();

            assert!(matches!(
                convert_rel(raw, &BTreeMap::new()),
                Err(Error::UnsupportedSetOp(value)) if value == legacy_set_op
            ));
        }
    }

