    #[test]
    fn sort_bound_source_is_validated_before_duplicate_provenance_is_cleared() {
        let mut exact: CalciteRex = serde_json::from_value(serde_json::json!({
            "kind": "LITERAL",
            "class": "RexLiteral",
            "text": "10",
            "type": "INTEGER",
            "sourceSql": "10",
            "sourceNodeId": "1:1-1:2",
            "sourceText": "10",
            "sourceKind": "LITERAL",
            "literalTypeName": "DECIMAL",
            "literalValue": "10",
            "literalValue2": "10"
        }))
        .unwrap();
        hydrate_current_wrapper_rex(&mut exact);
        let scalar = optional_rex_scalar(Some(exact.clone()), &BTreeMap::new())
            .unwrap()
            .unwrap();
        assert!(scalar.source.is_none());
        assert!(matches!(
            scalar.parsed,
            ScalarAst::TypeAnnotation { expr, ty }
                if ty == "INTEGER"
                    && matches!(expr.as_ref(), ScalarAst::Literal { raw } if raw == "10")
        ));

        let mut missing_source = exact;
        missing_source.source_sql = None;
        let scalar = optional_rex_scalar(Some(missing_source.clone()), &BTreeMap::new())
            .unwrap()
            .unwrap();
        assert!(scalar.source.is_none());

        missing_source.source_node_id = None;
        missing_source.source_text = None;
        let error = optional_rex_scalar(Some(missing_source), &BTreeMap::new()).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("no independently parsed source SQL"),
            "{error}"
        );
    }

