    fn conjunctive_having_provenance_file() -> CalciteFile {
        const SQL: &str = "select a from R group by a having a = 1 AND a = 2";
        let mut raw = filter_aggregate_provenance_file(
            Some("HAVING"),
            Some("1:1-1:49"),
            Some("1:1-1:49"),
            true,
        );
        raw.queries[0].sql = SQL.to_owned();
        let filter = raw.queries[0].rel.as_mut().unwrap();
        filter.inputs[0].source_grouping = Some(exact_test_ordinary_grouping(ExactTestGrouping {
            select: ExactTestSource {
                node_id: "1:1-1:49",
                text: SQL,
            },
            group: ExactTestSource {
                node_id: "1:17-1:26",
                text: "group by a",
            },
            operand: ExactTestSource {
                node_id: "1:26-1:26",
                text: "a",
            },
            group_index: 0,
            source_has_where: false,
            source_has_having: true,
        }));
        filter.source_node_id = Some("1:1-1:49".to_owned());
        filter.source_sql = Some(SQL.to_owned());
        filter.source_text = Some(SQL.to_owned());
        filter.inputs[0].inputs[0].source_query_block_id = Some("1:1-1:49".to_owned());
        let scan = &mut filter.inputs[0].inputs[0].inputs[0];
        scan.source_sql = Some(SQL.to_owned());
        scan.source_node_id = Some("1:1-1:49".to_owned());
        scan.source_text = Some(SQL.to_owned());
        scan.source_query_block_id = Some("1:1-1:49".to_owned());
        scan.source_table.as_mut().unwrap().query_block_id = "1:1-1:49".to_owned();

        let mut left = filter.condition_rex.take().unwrap();
        let mut right = left.clone();
        right.text = Some("=($0, 2)".to_owned());
        right.source_sql = Some("a = 2".to_owned());
        right.source_node_id = Some("1:45-1:49".to_owned());
        right.source_text = Some("a = 2".to_owned());
        right.operands[0].source_node_id = Some("1:45-1:45".to_owned());
        right.operands[0].source_text = Some("a".to_owned());
        right.operands[1].text = Some("2".to_owned());
        right.operands[1].source_sql = Some("2".to_owned());
        right.operands[1].source_node_id = Some("1:49-1:49".to_owned());
        right.operands[1].source_text = Some("2".to_owned());
        right.operands[1].literal_value = Some("2".to_owned());
        right.operands[1].literal_value2 = Some("2".to_owned());

        left.source_node_id = Some("1:35-1:39".to_owned());
        filter.condition_rex = Some(
            serde_json::from_value(serde_json::json!({
                "kind": "AND",
                "class": "RexCall",
                "text": "AND(=($0, 1), =($0, 2))",
                "type": "BOOLEAN",
                "operator": "AND",
                "opKind": "AND",
                "sourceSql": "a = 1 AND a = 2",
                "sourceNodeId": "1:35-1:49",
                "sourceText": "a = 1 AND a = 2",
                "sourceKind": "AND",
                "sourceOperator": "AND",
                "operands": [left, right]
            }))
            .unwrap(),
        );
        let marker = filter.source_native_having.as_mut().unwrap();
        marker.query_block_id = "1:1-1:49".to_owned();
        marker.owner_node_id = "1:1-1:49".to_owned();
        marker.source_owner_sql = SQL.to_owned();
        marker.source_owner_text = SQL.to_owned();
        marker.source_select_sql = SQL.to_owned();
        marker.source_select_text = SQL.to_owned();
        marker.source_condition_node_id = "1:35-1:49".to_owned();
        marker.source_condition_sql = "a = 1 AND a = 2".to_owned();
        marker.source_condition_text = "a = 1 AND a = 2".to_owned();
        marker.generated_condition_sql = "AND(=($0, 1), =($0, 2))".to_owned();
        let first = marker.operand_bindings[0].clone();
        marker.operand_bindings = vec![
            CalciteNativeHavingOperandBinding {
                path: "$.0.0".to_owned(),
                ..first.clone()
            },
            CalciteNativeHavingOperandBinding {
                path: "$.1.0".to_owned(),
                ..first
            },
        ];
        hydrate_current_wrapper_file(&mut raw);
        raw
    }

