    #[test]
    fn forged_declarative_having_attestation_is_rejected() {
        let pristine = filter_aggregate_provenance_file(
            Some("HAVING"),
            Some("1:1-1:39"),
            Some("1:1-1:39"),
            true,
        );
        let mut wrong_source_binding = pristine.clone();
        wrong_source_binding.queries[0]
            .rel
            .as_mut()
            .unwrap()
            .source_native_having
            .as_mut()
            .unwrap()
            .operand_bindings[0]
            .source_sql = "different_key".to_owned();
        assert!(convert_raw_file(wrong_source_binding).is_ok());
        let mut wrong_index = pristine.clone();
        wrong_index.queries[0]
            .rel
            .as_mut()
            .unwrap()
            .source_native_having
            .as_mut()
            .unwrap()
            .operand_bindings[0]
            .aggregate_output_index = 1;
        let mut wrong_generated_condition = pristine;
        wrong_generated_condition.queries[0]
            .rel
            .as_mut()
            .unwrap()
            .source_native_having
            .as_mut()
            .unwrap()
            .generated_condition_sql = "=($0, 2)".to_owned();
        let mut coherent_but_statement_stale = filter_aggregate_provenance_file(
            Some("HAVING"),
            Some("1:1-1:39"),
            Some("1:1-1:39"),
            true,
        );
        {
            let filter = coherent_but_statement_stale.queries[0]
                .rel
                .as_mut()
                .unwrap();
            filter.source_sql = Some("select a from R group by a having a = 2".to_owned());
            let marker = filter.source_native_having.as_mut().unwrap();
            marker.source_owner_sql = "select a from R group by a having a = 2".to_owned();
            marker.source_select_sql = "select a from R group by a having a = 2".to_owned();
            marker.source_select_text = "select a from R group by a having a = 2".to_owned();
            marker.source_condition_sql = "a = 2".to_owned();
            marker.source_condition_text = "a = 2".to_owned();
            filter.condition_rex.as_mut().unwrap().source_sql = Some("a = 2".to_owned());
        }
        let mut broken_alias_lineage = filter_aggregate_provenance_file(
            Some("HAVING"),
            Some("1:1-1:39"),
            Some("1:1-1:39"),
            true,
        );
        broken_alias_lineage.queries[0].rel.as_mut().unwrap().inputs[0].row_type[0].name =
            "aggregate_only_alias".to_owned();
        let mut disconnected_condition = filter_aggregate_provenance_file(
            Some("HAVING"),
            Some("1:1-1:39"),
            Some("1:1-1:39"),
            true,
        );
        {
            let filter = disconnected_condition.queries[0].rel.as_mut().unwrap();
            let marker = filter.source_native_having.as_mut().unwrap();
            marker.source_condition_sql = "a = 2".to_owned();
            marker.generated_condition_sql = "=($0, 2)".to_owned();
            let condition = filter.condition_rex.as_mut().unwrap();
            condition.text = Some("=($0, 2)".to_owned());
            condition.source_sql = Some("a = 2".to_owned());
            let literal = &mut condition.operands[1];
            literal.text = Some("2".to_owned());
            literal.source_sql = Some("2".to_owned());
            literal.literal_value = Some("2".to_owned());
            literal.literal_value2 = Some("2".to_owned());
            // The exact parser span/text remains the original source `1`;
            // changing it too would be rejected by the statement binder.
        }
        for raw in [
            wrong_index,
            wrong_generated_condition,
            coherent_but_statement_stale,
            broken_alias_lineage,
            disconnected_condition,
        ] {
            assert!(matches!(
                convert_raw_file(raw),
                Err(Error::InvalidRelSourceProvenance(_))
            ));
        }
    }

    #[test]
    fn native_having_requires_direct_distinct_ordered_source_ast_edges() {
        convert_raw_file(conjunctive_having_provenance_file())
            .expect("pristine conjunctive HAVING has direct ordered source edges");

        let mut duplicated = conjunctive_having_provenance_file();
        {
            let filter = duplicated.queries[0].rel.as_mut().unwrap();
            let condition = filter.condition_rex.as_mut().unwrap();
            condition.operands[1] = condition.operands[0].clone();
            condition.text = Some("AND(=($0, 1), =($0, 1))".to_owned());
            filter
                .source_native_having
                .as_mut()
                .unwrap()
                .generated_condition_sql = condition.text.clone().unwrap();
        }

        let mut omitted = conjunctive_having_provenance_file();
        {
            let filter = omitted.queries[0].rel.as_mut().unwrap();
            let condition = filter.condition_rex.as_mut().unwrap();
            condition.operands.pop();
            condition.text = Some("AND(=($0, 1))".to_owned());
            let marker = filter.source_native_having.as_mut().unwrap();
            marker.generated_condition_sql = condition.text.clone().unwrap();
            marker.operand_bindings.pop();
        }

        let mut borrowed_nested = conjunctive_having_provenance_file();
        {
            let filter = borrowed_nested.queries[0].rel.as_mut().unwrap();
            let condition = filter.condition_rex.as_mut().unwrap();
            condition.operands[1] = condition.operands[0].operands[0].clone();
            condition.text = Some("AND(=($0, 1), $0)".to_owned());
            let marker = filter.source_native_having.as_mut().unwrap();
            marker.generated_condition_sql = condition.text.clone().unwrap();
            marker.operand_bindings[1].path = "$.1".to_owned();
        }

        let mut swapped_noncommutative = filter_aggregate_provenance_file(
            Some("HAVING"),
            Some("1:1-1:39"),
            Some("1:1-1:39"),
            true,
        );
        {
            let filter = swapped_noncommutative.queries[0].rel.as_mut().unwrap();
            let condition = filter.condition_rex.as_mut().unwrap();
            condition.kind = Some("GREATER_THAN".to_owned());
            condition.op_kind = Some("GREATER_THAN".to_owned());
            condition.operator = Some(">".to_owned());
            condition.source_kind = Some("GREATER_THAN".to_owned());
            condition.source_operator = Some(">".to_owned());
            condition.text = Some(">(1, $0)".to_owned());
            condition.source_sql = Some("a > 1".to_owned());
            condition.source_text = Some("a > 1".to_owned());
            condition.operands.swap(0, 1);
            filter.source_sql = Some("select a from R group by a having a > 1".to_owned());
            let marker = filter.source_native_having.as_mut().unwrap();
            marker.source_owner_sql = filter.source_sql.clone().unwrap();
            marker.source_owner_text = filter.source_sql.clone().unwrap();
            marker.source_select_sql = filter.source_sql.clone().unwrap();
            marker.source_select_text = filter.source_sql.clone().unwrap();
            marker.source_condition_sql = "a > 1".to_owned();
            marker.source_condition_text = "a > 1".to_owned();
            marker.generated_condition_sql = condition.text.clone().unwrap();
            marker.operand_bindings[0].path = "$.1".to_owned();
            swapped_noncommutative.queries[0].sql =
                filter.source_sql.clone().expect("source HAVING SQL");
        }

        for raw in [duplicated, omitted, borrowed_nested, swapped_noncommutative] {
            assert!(matches!(
                convert_raw_file(raw),
                Err(Error::InvalidRelSourceProvenance(_))
            ));
        }
    }

    #[test]
    fn mixed_wildcard_project_binds_expansion_and_following_identifier_by_position() {
        fn field(name: &str, ty: &str, precision: i32, scale: i32) -> serde_json::Value {
            serde_json::json!({
                "name": name,
                "type": ty,
                "nullable": true,
                "fullType": ty,
                "precision": precision,
                "scale": scale
            })
        }
        fn input_ref(index: usize, ty: &str, precision: i32, scale: i32) -> serde_json::Value {
            serde_json::json!({
                "kind": "INPUT_REF",
                "class": "RexInputRef",
                "text": format!("${index}"),
                "type": ty,
                "nullable": true,
                "fullType": ty,
                "precision": precision,
                "scale": scale,
                "index": index
            })
        }

        let statement = "SELECT t.*, t.id AS copied_id FROM t";
        let query_id = test_exact_span(statement);
        let table_id = exact_span_for_occurrence(statement, "t", 2);
        let mut project: CalciteRel = serde_json::from_value(serde_json::json!({
            "type": "LogicalProject",
            "rowType": [
                field("id", "INTEGER", 10, 0),
                field("value", "VARCHAR", -1, i32::MIN),
                field("copied_id", "INTEGER", 10, 0)
            ],
            "sourceSql": statement,
            "sourceNodeId": query_id,
            "sourceText": statement,
            "sourceKind": "SELECT",
            "sourceOperator": "SELECT",
            "sourceQueryBlockId": query_id,
            "sourceRootQueryBlockId": query_id,
            "projectRex": [
                input_ref(0, "INTEGER", 10, 0),
                input_ref(1, "VARCHAR", -1, i32::MIN),
                input_ref(0, "INTEGER", 10, 0)
            ],
            "inputs": [{
                "type": "LogicalTableScan",
                "rowType": [
                    field("id", "INTEGER", 10, 0),
                    field("value", "VARCHAR", -1, i32::MIN)
                ],
                "table": ["t"],
                "sourceQueryBlockId": query_id,
                "sourceRootQueryBlockId": query_id,
                "sourceTable": {
                    "kind": "DIRECT_BASE_TABLE",
                    "queryBlockId": query_id,
                    "relationNodeId": table_id,
                    "relationText": "t",
                    "tableNodeId": table_id,
                    "tableText": "t",
                    "tableNames": ["t"],
                    "tableQuoted": [false],
                    "aliasNodeId": null,
                    "aliasText": null,
                    "aliasNames": [],
                    "aliasQuoted": []
                }
            }]
        }))
        .unwrap();
        {
            let source = project.inputs[0].source_table.as_mut().unwrap();
            source.relation_occurrence_id = table_id.clone();
            source.output_lineage = serde_json::from_value(serde_json::json!([{
                "outputIndex": 0,
                "kind": "BASE_COLUMN",
                "relationOccurrenceId": table_id,
                "baseColumnIndex": 0,
                "baseColumnName": "id",
                "visibleColumnName": "id",
                "generatedFieldName": "id",
                "explicitColumnAlias": false,
                "columnAliasNodeId": null,
                "columnAliasText": null
            }, {
                "outputIndex": 1,
                "kind": "BASE_COLUMN",
                "relationOccurrenceId": table_id,
                "baseColumnIndex": 1,
                "baseColumnName": "value",
                "visibleColumnName": "value",
                "generatedFieldName": "value",
                "explicitColumnAlias": false,
                "columnAliasNodeId": null,
                "columnAliasText": null
            }]))
            .unwrap();
        }

        validate_project_select_item_source_order(
            &project,
            Some(statement),
            Some("LogicalUnion"),
            "rel",
        )
        .unwrap();

        let mut reordered_wildcard = project.clone();
        reordered_wildcard.project_rex.swap(0, 1);
        assert!(
            validate_project_select_item_source_order(
                &reordered_wildcard,
                Some(statement),
                Some("LogicalUnion"),
                "rel",
            )
            .is_err()
        );

        let mut borrowed_identifier = project.clone();
        borrowed_identifier.project_rex[2] =
            serde_json::from_value(input_ref(1, "VARCHAR", -1, i32::MIN)).unwrap();
        borrowed_identifier.row_type[2] = crate::calcite::CalciteField {
            name: "copied_id".to_owned(),
            ty: "VARCHAR".to_owned(),
            nullable: true,
            full_type: Some("VARCHAR".to_owned()),
            precision: Some(-1),
            scale: Some(i32::MIN),
            charset: None,
            type_collation: None,
        };
        assert!(
            validate_project_select_item_source_order(
                &borrowed_identifier,
                Some(statement),
                Some("LogicalUnion"),
                "rel",
            )
            .is_err()
        );

        let mut wrong_alias = project;
        wrong_alias.row_type[2].name = "wrong".to_owned();
        assert!(
            validate_project_select_item_source_order(
                &wrong_alias,
                Some(statement),
                Some("LogicalUnion"),
                "rel",
            )
            .is_err()
        );
    }

    #[test]
    fn native_having_binary_function_requires_exact_call_syntax_and_operand_order() {
        fn power_rex(source: &str, left_id: &str, right_id: &str) -> CalciteRex {
            serde_json::from_value(serde_json::json!({
                "kind": "OTHER_FUNCTION",
                "class": "RexCall",
                "operator": "POWER",
                "opKind": "OTHER_FUNCTION",
                "sourceNodeId": test_exact_span(source),
                "sourceText": source,
                "sourceKind": "OTHER_FUNCTION",
                "sourceOperator": "power",
                "operands": [{
                    "kind": "INPUT_REF",
                    "class": "RexInputRef",
                    "sourceNodeId": left_id,
                    "sourceText": "a",
                    "sourceKind": "IDENTIFIER"
                }, {
                    "kind": "LITERAL",
                    "class": "RexLiteral",
                    "sourceNodeId": right_id,
                    "sourceText": "0.5",
                    "sourceKind": "LITERAL"
                }]
            }))
            .unwrap()
        }

        let source = "POWER(a, 0.5)";
        let pristine = power_rex(
            source,
            &exact_span_for_occurrence(source, "a", 0),
            &exact_span_for_occurrence(source, "0.5", 0),
        );
        validate_native_having_call_source_edges(
            &pristine,
            source,
            parse_source_span_id(&test_exact_span(source)).unwrap(),
            source,
            NativeHavingRexSemantics {
                context: RexContext::General,
                source_role: ExactSourceRexRole::Value,
            },
            "$",
            None,
        )
        .unwrap();

        let mut swapped = pristine;
        swapped.operands.swap(0, 1);
        assert!(
            validate_native_having_call_source_edges(
                &swapped,
                source,
                parse_source_span_id(&test_exact_span(source)).unwrap(),
                source,
                NativeHavingRexSemantics {
                    context: RexContext::General,
                    source_role: ExactSourceRexRole::Value,
                },
                "$",
                None,
            )
            .is_err()
        );

        let infix = "a POWER 0.5";
        let forged = power_rex(
            infix,
            &exact_span_for_occurrence(infix, "a", 0),
            &exact_span_for_occurrence(infix, "0.5", 0),
        );
        assert!(
            validate_native_having_call_source_edges(
                &forged,
                infix,
                parse_source_span_id(&test_exact_span(infix)).unwrap(),
                infix,
                NativeHavingRexSemantics {
                    context: RexContext::General,
                    source_role: ExactSourceRexRole::Value,
                },
                "$",
                None,
            )
            .is_err()
        );
    }

    #[test]
    fn native_having_or_owns_only_exact_consecutive_in_expansion_groups() {
        fn generated_equality(source: &str, candidate: &str) -> CalciteRex {
            serde_json::from_value(serde_json::json!({
                "kind": "EQUALS",
                "class": "RexCall",
                "operator": "=",
                "opKind": "EQUALS",
                "sourceKind": "EQUALS",
                "sourceOperator": "=",
                "operands": [{
                    "kind": "INPUT_REF",
                    "class": "RexInputRef",
                    "sourceNodeId": exact_span_for_occurrence(source, "a", 0),
                    "sourceText": "a",
                    "sourceKind": "IDENTIFIER"
                }, {
                    "kind": "LITERAL",
                    "class": "RexLiteral",
                    "sourceNodeId": exact_span_for_occurrence(source, candidate, 0),
                    "sourceText": candidate,
                    "sourceKind": "LITERAL"
                }]
            }))
            .unwrap()
        }

        fn flattened_or(source: &str) -> CalciteRex {
            serde_json::from_value(serde_json::json!({
                "kind": "OR",
                "class": "RexCall",
                "operator": "OR",
                "opKind": "OR",
                "sourceNodeId": test_exact_span(source),
                "sourceText": source,
                "sourceKind": "OR",
                "sourceOperator": "OR",
                "operands": [
                    generated_equality(source, "1"),
                    generated_equality(source, "2"),
                    {
                        "kind": "EQUALS",
                        "class": "RexCall",
                        "operator": "=",
                        "opKind": "EQUALS",
                        "sourceNodeId": exact_span_for_occurrence(source, "b = 9", 0),
                        "sourceText": "b = 9",
                        "sourceKind": "EQUALS",
                        "sourceOperator": "="
                    }
                ]
            }))
            .unwrap()
        }

        let source = "(a IN (1, 2, 2) OR b = 9)";
        let validate = |rex: &CalciteRex| {
            validate_native_having_call_source_edges(
                rex,
                source,
                parse_source_span_id(&test_exact_span(source)).unwrap(),
                source,
                NativeHavingRexSemantics {
                    context: RexContext::General,
                    source_role: ExactSourceRexRole::Predicate,
                },
                "$",
                None,
            )
        };
        let pristine = flattened_or(source);
        validate(&pristine).unwrap();

        let mut swapped_candidates = pristine.clone();
        swapped_candidates.operands.swap(0, 1);
        assert!(validate(&swapped_candidates).is_err());

        let mut borrowed_non_in = pristine.clone();
        borrowed_non_in.operands[2].source_node_id =
            Some(exact_span_for_occurrence(source, "a", 0));
        borrowed_non_in.operands[2].source_text = Some("a".to_owned());
        assert!(validate(&borrowed_non_in).is_err());

        let mut extra_comparison = pristine;
        extra_comparison
            .operands
            .insert(2, generated_equality(source, "2"));
        assert!(validate(&extra_comparison).is_err());

        assert!(!direct_source_is_positive_in("a NOT IN (1, 2)"));
        assert!(!direct_source_is_positive_in("a IN (SELECT b FROM t)"));
        assert!(direct_source_is_positive_in("((a IN (1, 2)))"));
    }

    #[test]
    fn native_having_and_allows_only_one_exact_trailing_duplicate_conjunct() {
        fn generated_unique_conjuncts(source: &str) -> CalciteRex {
            serde_json::from_value(serde_json::json!({
                "kind": "AND",
                "class": "RexCall",
                "operator": "AND",
                "opKind": "AND",
                "sourceNodeId": test_exact_span(source),
                "sourceText": source,
                "sourceKind": "AND",
                "sourceOperator": "AND",
                "operands": [{
                    "kind": "EQUALS",
                    "class": "RexCall",
                    "sourceNodeId": exact_span_for_occurrence(source, "a = 1", 0),
                    "sourceText": "a = 1",
                    "sourceKind": "EQUALS",
                    "sourceOperator": "="
                }, {
                    "kind": "EQUALS",
                    "class": "RexCall",
                    "sourceNodeId": exact_span_for_occurrence(source, "a = 2", 0),
                    "sourceText": "a = 2",
                    "sourceKind": "EQUALS",
                    "sourceOperator": "="
                }]
            }))
            .unwrap()
        }
        let validate = |rex: &CalciteRex, source: &str| {
            validate_native_having_call_source_edges(
                rex,
                source,
                parse_source_span_id(&test_exact_span(source)).unwrap(),
                source,
                NativeHavingRexSemantics {
                    context: RexContext::General,
                    source_role: ExactSourceRexRole::Predicate,
                },
                "$",
                None,
            )
        };

        let exact_duplicate = "a = 1 AND a = 2 AND a = 1";
        let pristine = generated_unique_conjuncts(exact_duplicate);
        validate(&pristine, exact_duplicate).unwrap();

        let nonduplicate = "a = 1 AND a = 2 AND a = 3";
        assert!(validate(&generated_unique_conjuncts(nonduplicate), nonduplicate).is_err());
        let repeated_twice = "a = 1 AND a = 2 AND a = 1 AND a = 1";
        assert!(validate(&generated_unique_conjuncts(repeated_twice), repeated_twice,).is_err());
        let mut swapped = pristine;
        swapped.operands.swap(0, 1);
        assert!(validate(&swapped, exact_duplicate).is_err());
    }

    #[test]
    fn exact_numeric_canonicalization_is_bounded_and_value_preserving() {
        for (raw, expected) in [
            ("1.00", "1"),
            ("001.2300e2", "123"),
            ("-0.00100", "-0.001"),
            ("1E+3", "1000"),
            ("0E-4000", "0"),
        ] {
            assert_eq!(canonical_exact_numeric(raw).as_deref(), Some(expected));
        }
        for raw in ["", ".", "1e", "1e4097", "nan", "inf", "--1"] {
            assert_eq!(canonical_exact_numeric(raw), None, "{raw}");
        }
    }

