    #[test]
    fn obsolete_parallel_query_representations_are_rejected() {
        for obsolete in [
            serde_json::json!({"relText": "LogicalValues(tuples=[[{ 1 }]])"}),
            serde_json::json!({"sqlAst": {"kind": "VALUES"}}),
        ] {
            let mut query = serde_json::json!({
                "sql": "values (1)",
                "rel": {
                    "type": "LogicalValues",
                    "rowType": [{"name": "EXPR$0", "type": "INTEGER", "nullable": false}],
                    "tuples": [[{
                        "kind": "LITERAL",
                        "class": "RexLiteral",
                        "text": "1",
                        "type": "INTEGER",
                        "literalTypeName": "INTEGER",
                        "literalValue": "1",
                        "literalValue2": "1"
                    }]],
                    "inputs": []
                }
            });
            query
                .as_object_mut()
                .expect("query object")
                .extend(obsolete.as_object().expect("obsolete field object").clone());
            let file = serde_json::json!({"schema": [], "queries": [query]});
            assert!(
                serde_json::from_value::<CalciteFile>(file).is_err(),
                "obsolete parallel representation must not be accepted"
            );
        }
    }

