    #[test]
    fn structured_rex_subquery_preserves_rel_tree() {
        let raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [
                {"name": "EMP", "columns": [{"name": "DEPTNO", "type": "INTEGER"}]},
                {"name": "DEPT", "columns": [{"name": "DEPTNO", "type": "INTEGER"}]}
              ],
              "queries": [{
                "sql": "select deptno from emp where deptno in (select deptno from dept)",
                "rel": {
                  "type": "LogicalFilter",
                  "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                  "conditionRex": {
                    "kind": "IN",
                    "class": "RexSubQuery",
                    "text": "IN($0, { LogicalProject(DEPTNO=[$0]) })",
                    "type": "BOOLEAN",
                    "nullable": true,
                    "operator": "IN",
                    "opKind": "IN",
                    "operands": [{"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "INTEGER", "index": 0}],
                    "subqueryRel": {
                      "type": "LogicalProject",
                      "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                      "projectRex": [{"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "INTEGER", "index": 0}],
                      "inputs": [{
                        "type": "LogicalTableScan",
                        "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                        "table": ["DEPT"],
                        "inputs": []
                      }]
                    }
                  },
                  "inputs": [{
                    "type": "LogicalTableScan",
                    "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                    "table": ["EMP"],
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();

        // This test isolates structured Rex-to-IR conversion. File-level
        // source/query-shape admission is covered by wrapper-backed tests.
        let rel = convert_current_wrapper_test_rel(
            raw.queries.into_iter().next().unwrap().rel.unwrap(),
            &BTreeMap::new(),
        )
        .unwrap();
        let RelExpr::Filter { predicate, .. } = &rel else {
            panic!("expected filter");
        };
        let ScalarAst::Call { op, args, .. } = &predicate.parsed else {
            panic!("expected IN call");
        };
        assert_eq!(op, &ScalarOp::In);
        assert!(matches!(args.last(), Some(ScalarAst::RelSubquery { .. })));
    }

    #[test]
    fn structured_rex_field_access_preserves_correlated_ref() {
        let raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [
                {"name": "EMP", "columns": [{"name": "DEPTNO", "type": "INTEGER"}]},
                {"name": "DEPT", "columns": [{"name": "DEPTNO", "type": "INTEGER"}]}
              ],
              "queries": [{
                "sql": "select deptno from emp where exists (select 1 from dept)",
                "rel": {
                  "type": "LogicalFilter",
                  "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                  "conditionRex": {
                    "kind": "EXISTS",
                    "class": "RexSubQuery",
                    "text": "EXISTS({ LogicalFilter(condition=[=($0, $cor0.DEPTNO)]) })",
                    "type": "BOOLEAN",
                    "nullable": true,
                    "operator": "EXISTS",
                    "opKind": "EXISTS",
                    "operands": [],
                    "subqueryRel": {
                      "type": "LogicalFilter",
                      "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                      "conditionRex": {
                        "kind": "EQUALS",
                        "class": "RexCall",
                        "text": "=($0, $cor0.DEPTNO)",
                        "type": "BOOLEAN",
                        "nullable": true,
                        "operator": "=",
                        "opKind": "EQUALS",
                        "operands": [
                          {"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "INTEGER", "index": 0},
                          {
                            "kind": "FIELD_ACCESS",
                            "class": "RexFieldAccess",
                            "text": "$cor0.DEPTNO",
                            "type": "INTEGER",
                            "precision": 10,
                            "nullable": true,
                            "fieldName": "DEPTNO",
                            "fieldIndex": 0,
                            "referenceExpr": {
                              "kind": "CORREL_VARIABLE",
                              "class": "RexCorrelVariable",
                              "text": "$cor0",
                              "type": "RecordType(INTEGER DEPTNO)",
                              "correlationId": 0,
                              "correlationName": "$cor0"
                            }
                          }
                        ]
                      },
                      "inputs": [{
                        "type": "LogicalTableScan",
                        "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                        "table": ["DEPT"],
                        "inputs": []
                      }]
                    }
                  },
                  "inputs": [{
                    "type": "LogicalTableScan",
                    "rowType": [{"name": "DEPTNO", "type": "INTEGER", "nullable": true}],
                    "table": ["EMP"],
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();

        // This test isolates structured correlated Rex conversion; exact SQL
        // ownership of correlated subqueries is exercised separately.
        let rel = convert_current_wrapper_test_rel(
            raw.queries.into_iter().next().unwrap().rel.unwrap(),
            &BTreeMap::new(),
        )
        .unwrap();
        let RelExpr::Filter { predicate, .. } = &rel else {
            panic!("expected outer filter");
        };
        let ScalarAst::Call { args, .. } = &predicate.parsed else {
            panic!("expected EXISTS call");
        };
        let Some(ScalarAst::RelSubquery { rel }) = args.last() else {
            panic!("expected structured subquery");
        };
        let RelExpr::Filter {
            predicate: inner_predicate,
            ..
        } = rel.as_ref()
        else {
            panic!("expected inner filter");
        };
        let ScalarAst::Call { args, .. } = &inner_predicate.parsed else {
            panic!("expected inner predicate call");
        };
        assert!(matches!(
            &args[1],
            ScalarAst::CorrelatedRef {
                correlation,
                field,
                index: Some(0),
                ty: SqlType::Integer,
            } if correlation == "$cor0" && field == "DEPTNO"
        ));
    }

