            condition.source_sql = Some("job = name".to_owned());
            condition.source_kind = Some("EQUALS".to_owned());
            condition.source_operator = Some("=".to_owned());
            let correlated = &mut condition.operands[0];
            correlated.nullable = true;
            correlated.source_sql = Some("job".to_owned());
            correlated.source_kind = Some("IDENTIFIER".to_owned());
            correlated.source_identifier_names = vec!["job".to_owned()];
