    #[test]
    fn decimal_precision_and_scale_survive_project_conversion() {
        let mut raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [{"name": "t", "columns": [{"name": "amount", "type": "DECIMAL", "precision": 10, "scale": 2}]}],
              "queries": [{
                "sql": "select cast(amount as decimal(10, 2)) as amount_out from T",
                "rel": {
                  "type": "LogicalProject",
                  "rowType": [{"name": "amount_out", "type": "DECIMAL", "nullable": true, "precision": 10, "scale": 2}],
                  "projectRex": [{
                    "kind": "CAST",
                    "class": "RexCall",
                    "text": "CAST($0):DECIMAL(10, 2)",
                    "type": "DECIMAL",
                    "precision": 10,
                    "scale": 2,
                    "operator": "CAST",
                    "opKind": "CAST",
                    "operands": [{"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "DECIMAL", "index": 0, "precision": 10, "scale": 2}]
                  }],
                  "inputs": [{
                    "type": "LogicalTableScan",
                    "rowType": [{"name": "amount", "type": "DECIMAL", "nullable": true, "precision": 10, "scale": 2}],
                    "table": ["t"],
                    "sourceTable": {
                      "kind": "DIRECT_BASE_TABLE",
                      "queryBlockId": "1:1-1:58",
                      "relationNodeId": "1:58-1:58",
                      "relationText": "T",
                      "tableNodeId": "1:58-1:58",
                      "tableText": "T",
                      "tableNames": ["t"],
                      "tableQuoted": [false],
                      "aliasNodeId": null,
                      "aliasText": null,
                      "aliasNames": [],
                      "aliasQuoted": []
                    },
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();

        {
            let statement = raw.queries[0].sql.clone();
            let project = raw.queries[0].rel.as_mut().unwrap();
            project.source_sql = Some(statement);
            project.source_kind = Some("SELECT".to_owned());
            project.source_operator = Some("SELECT".to_owned());
            let cast = &mut project.project_rex[0];
            cast.source_sql = Some("cast(amount as decimal(10, 2))".to_owned());
            cast.source_kind = Some("CAST".to_owned());
            cast.source_operator = Some("CAST".to_owned());
            let amount = &mut cast.operands[0];
            amount.nullable = true;
            amount.source_sql = Some("amount".to_owned());
            amount.source_kind = Some("IDENTIFIER".to_owned());
            amount.source_identifier_names = vec!["amount".to_owned()];
            amount.source_identifier_quoted = vec![false];
        }
        bind_test_file_to_statements(&mut raw);

        let ir = convert_raw_file(raw).unwrap();
        assert_eq!(
            ir.schema.tables[0].columns[0].ty,
            SqlType::decimal(Some(10), Some(2))
        );
        assert_eq!(
            ir.queries[0].output()[0].ty,
            SqlType::decimal(Some(10), Some(2))
        );
        let RelExpr::Project { exprs, .. } = &ir.queries[0].rel else {
            panic!("expected project");
        };
        let ScalarAst::TypeAnnotation { ty, .. } = &exprs[0].parsed else {
            panic!("expected decimal type annotation");
        };
        assert_eq!(ty, "DECIMAL(10,2)");
    }

    #[test]
    fn decimal_rex_call_result_keeps_operator_ast() {
        let mut raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [{"name": "t", "columns": [
                {"name": "a", "type": "DECIMAL", "precision": 10, "scale": 2},
                {"name": "b", "type": "DECIMAL", "precision": 10, "scale": 2}
              ]}],
              "queries": [{
                "sql": "select a + b as sum_ab from T",
                "rel": {
                  "type": "LogicalProject",
                  "rowType": [{"name": "sum_ab", "type": "DECIMAL", "nullable": true, "precision": 11, "scale": 2}],
                  "projectRex": [{
                    "kind": "PLUS",
                    "class": "RexCall",
                    "text": "+($0, $1)",
                    "type": "DECIMAL",
                    "precision": 11,
                    "scale": 2,
                    "operator": "+",
                    "opKind": "PLUS",
                    "operands": [
                      {"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "DECIMAL", "index": 0, "precision": 10, "scale": 2},
                      {"kind": "INPUT_REF", "class": "RexInputRef", "text": "$1", "type": "DECIMAL", "index": 1, "precision": 10, "scale": 2}
                    ]
                  }],
                  "inputs": [{
                    "type": "LogicalTableScan",
                    "rowType": [
                      {"name": "a", "type": "DECIMAL", "nullable": true, "precision": 10, "scale": 2},
                      {"name": "b", "type": "DECIMAL", "nullable": true, "precision": 10, "scale": 2}
                    ],
                    "table": ["t"],
                    "sourceTable": {
                      "kind": "DIRECT_BASE_TABLE",
                      "queryBlockId": "1:1-1:29",
                      "relationNodeId": "1:29-1:29",
                      "relationText": "T",
                      "tableNodeId": "1:29-1:29",
                      "tableText": "T",
                      "tableNames": ["t"],
                      "tableQuoted": [false],
                      "aliasNodeId": null,
                      "aliasText": null,
                      "aliasNames": [],
                      "aliasQuoted": []
                    },
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();

        {
            let statement = raw.queries[0].sql.clone();
            let project = raw.queries[0].rel.as_mut().unwrap();
            project.source_sql = Some(statement);
            project.source_kind = Some("SELECT".to_owned());
            project.source_operator = Some("SELECT".to_owned());
            let plus = &mut project.project_rex[0];
            plus.source_sql = Some("a + b".to_owned());
            plus.source_kind = Some("PLUS".to_owned());
            plus.source_operator = Some("+".to_owned());
            for (operand, name) in plus.operands.iter_mut().zip(["a", "b"]) {
                operand.nullable = true;
                operand.source_sql = Some(name.to_owned());
                operand.source_kind = Some("IDENTIFIER".to_owned());
                operand.source_identifier_names = vec![name.to_owned()];
                operand.source_identifier_quoted = vec![false];
            }
        }
        bind_test_file_to_statements(&mut raw);

        let ir = convert_raw_file(raw).unwrap();
        let RelExpr::Project { exprs, .. } = &ir.queries[0].rel else {
            panic!("expected project");
        };
        assert!(matches!(
            &exprs[0].parsed,
            ScalarAst::Call {
                op: ScalarOp::Plus,
                ..
            }
        ));
    }

    #[test]
    fn decimal_without_explicit_scale_defaults_to_zero() {
        let mut raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [{"name": "t", "columns": [{"name": "amount", "type": "DECIMAL", "precision": 10}]}],
              "queries": [{
                "sql": "select cast(amount as decimal(10)) as amount_out from T",
                "rel": {
                  "type": "LogicalProject",
                  "rowType": [{"name": "amount_out", "type": "DECIMAL", "nullable": true, "precision": 10}],
                  "projectRex": [{
                    "kind": "CAST",
                    "class": "RexCall",
                    "text": "CAST($0):DECIMAL(10)",
                    "type": "DECIMAL",
                    "precision": 10,
                    "operator": "CAST",
                    "opKind": "CAST",
                    "operands": [{"kind": "INPUT_REF", "class": "RexInputRef", "text": "$0", "type": "DECIMAL", "index": 0, "precision": 10}]
                  }],
                  "inputs": [{
                    "type": "LogicalTableScan",
                    "rowType": [{"name": "amount", "type": "DECIMAL", "nullable": true, "precision": 10}],
                    "table": ["t"],
                    "sourceTable": {
                      "kind": "DIRECT_BASE_TABLE",
                      "queryBlockId": "1:1-1:55",
                      "relationNodeId": "1:55-1:55",
                      "relationText": "T",
                      "tableNodeId": "1:55-1:55",
                      "tableText": "T",
                      "tableNames": ["t"],
                      "tableQuoted": [false],
                      "aliasNodeId": null,
                      "aliasText": null,
                      "aliasNames": [],
                      "aliasQuoted": []
                    },
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();

        {
            let statement = raw.queries[0].sql.clone();
            let project = raw.queries[0].rel.as_mut().unwrap();
            project.source_sql = Some(statement);
            project.source_kind = Some("SELECT".to_owned());
            project.source_operator = Some("SELECT".to_owned());
            let cast = &mut project.project_rex[0];
            cast.source_sql = Some("cast(amount as decimal(10))".to_owned());
            cast.source_kind = Some("CAST".to_owned());
            cast.source_operator = Some("CAST".to_owned());
            let amount = &mut cast.operands[0];
            amount.nullable = true;
            amount.source_sql = Some("amount".to_owned());
            amount.source_kind = Some("IDENTIFIER".to_owned());
            amount.source_identifier_names = vec!["amount".to_owned()];
            amount.source_identifier_quoted = vec![false];
        }
        bind_test_file_to_statements(&mut raw);

        let ir = convert_raw_file(raw).unwrap();
        assert_eq!(
            ir.schema.tables[0].columns[0].ty,
            SqlType::decimal(Some(10), Some(0))
        );
        assert_eq!(
            ir.queries[0].output()[0].ty,
            SqlType::decimal(Some(10), Some(0))
        );
        let RelExpr::Project { exprs, .. } = &ir.queries[0].rel else {
            panic!("expected project");
        };
        let ScalarAst::TypeAnnotation { ty, .. } = &exprs[0].parsed else {
            panic!("expected decimal type annotation");
        };
        // The exact SQL spelling omits scale, while PostgreSQL typing above
        // still interprets that omitted scale as zero.
        assert_eq!(ty, "DECIMAL(10)");
    }

