    #[test]
    fn decimal_cast_literal_uses_source_sql_before_calcite_rounding() {
        let mut raw: CalciteFile = serde_json::from_str(
            r#"
            {
              "schema": [],
              "queries": [{
                "sql": "SELECT CAST('1.235' AS DECIMAL(4, 2))",
                "rel": {
                  "type": "LogicalProject",
                  "rowType": [{"name": "amount", "type": "DECIMAL", "nullable": false, "precision": 4, "scale": 2}],
                  "projectRex": [{
                    "kind": "LITERAL",
                    "class": "RexLiteral",
                    "text": "1.23:DECIMAL(4, 2)",
                    "type": "DECIMAL",
                    "precision": 4,
                    "scale": 2,
                    "literalTypeName": "DECIMAL",
                    "literalValue": "1.23",
                    "sourceSql": "CAST('1.235' AS DECIMAL(4, 2))",
                    "sourceNodeId": "1:8-1:37",
                    "sourceText": "CAST('1.235' AS DECIMAL(4, 2))"
                  }],
                  "inputs": [{
                    "type": "LogicalValues",
                    "rowType": [],
                    "tuples": [],
                    "inputs": []
                  }]
                }
              }]
            }
            "#,
        )
        .unwrap();
        bind_test_file_to_statements(&mut raw);

        let ir = convert_raw_file(raw).unwrap();
        let RelExpr::Project { exprs, .. } = &ir.queries[0].rel else {
            panic!("expected project");
        };
        let ScalarAst::TypeAnnotation { expr, ty } = &exprs[0].parsed else {
            panic!("expected decimal type annotation");
        };
        assert_eq!(ty, "DECIMAL(4,2)");
        let ScalarAst::Call { op, args, .. } = expr.as_ref() else {
            panic!("expected preserved explicit cast");
        };
        assert_eq!(op, &ScalarOp::Cast);
        assert!(matches!(
            args.as_slice(),
            [ScalarAst::TypeAnnotation { expr, ty }]
                if ty == "NUMERIC"
                    && matches!(expr.as_ref(), ScalarAst::Literal { raw } if raw == "1.235")
        ));
    }

