    #[test]
    fn character_comparison_cast_requires_one_exact_source_peer() {
        let cast: CalciteRex = serde_json::from_value(serde_json::json!({
            "kind": "CAST",
            "class": "RexCall",
            "text": "CAST($0):CHAR(3)",
            "type": "CHAR",
            "nullable": true,
            "fullType": "CHAR(3)",
            "precision": 3,
            "scale": i32::MIN,
            "charset": "ISO-8859-1",
            "typeCollation": CALCITE_1_42_STALE_TYPE_COLLATION,
            "sourceSql": "c",
            "sourceNodeId": "1:1-1:1",
            "sourceText": "c",
            "sourceKind": "IDENTIFIER",
            "sourceIdentifierNames": ["c"],
            "sourceIdentifierQuoted": [false],
            "operator": "CAST",
            "opKind": "CAST",
            "operands": [{
                "kind": "INPUT_REF",
                "class": "RexInputRef",
                "text": "$0",
                "type": "CHAR",
                "nullable": true,
                "fullType": "CHAR(2)",
                "precision": 2,
                "scale": i32::MIN,
                "charset": "ISO-8859-1",
                "typeCollation": CALCITE_1_42_STALE_TYPE_COLLATION,
                "index": 0,
                "sourceSql": "c",
                "sourceNodeId": "1:1-1:1",
                "sourceText": "c",
                "sourceKind": "IDENTIFIER",
                "sourceIdentifierNames": ["c"],
                "sourceIdentifierQuoted": [false]
            }]
        }))
        .unwrap();
        let literal: CalciteRex = serde_json::from_value(serde_json::json!({
            "kind": "LITERAL",
            "class": "RexLiteral",
            "text": "'abc'",
            "type": "CHAR",
            "nullable": false,
            "fullType": "CHAR(3) NOT NULL",
            "precision": 3,
            "scale": i32::MIN,
            "charset": "ISO-8859-1",
            "typeCollation": CALCITE_1_42_STALE_TYPE_COLLATION,
            "sourceSql": "'abc'",
            "sourceNodeId": "1:5-1:9",
            "sourceText": "'abc'",
            "sourceKind": "LITERAL",
            "literalTypeName": "CHAR",
            "literalValue": "_ISO-8859-1'abc'",
            "literalValue2": "abc",
            "literalValueAsString": "abc"
        }))
        .unwrap();
        assert!(exact_postgres_character_comparison_cast_is_absent(
            &cast, &literal
        ));

        let mut forged_literal = literal;
        forged_literal.source_text = Some("'abd'".to_owned());
        assert!(!exact_postgres_character_comparison_cast_is_absent(
            &cast,
            &forged_literal,
        ));
        let mut forged_cast = cast;
        forged_cast.source_operator = Some("CAST".to_owned());
        assert!(!exact_postgres_character_comparison_cast_is_absent(
            &forged_cast,
            &forged_literal,
        ));
    }

