    #[test]
    fn implicit_character_width_cast_over_exact_bare_literal_is_absent_only_with_all_views() {
        let rex = exact_implicit_character_literal_cast();
        assert!(implicit_exact_character_literal_cast_is_absent(&rex));
        assert!(matches!(
            calcite_rex_ast(&rex, &BTreeMap::new()).unwrap(),
            ScalarAst::Literal { raw } if raw == "'store'"
        ));
        let source = calcite_rex_source_provenance(&rex)
            .expect("the exact bare literal retains source authority");
        assert_eq!(source.sql.as_deref(), Some("'store'"));
        assert_eq!(source.kind.as_deref(), Some("LITERAL"));
        assert!(source.operator.is_none());
        assert!(
            source.operands.is_empty(),
            "the erased Calcite-only CHAR carrier must not survive solely in provenance"
        );

        let mut forged = Vec::new();

        let mut parent_source = rex.clone();
        parent_source.source_text = Some("'catalog'".to_owned());
        forged.push(("parent source", parent_source));

        let mut child_source = rex.clone();
        child_source.operands[0].source_text = Some("'catalog'".to_owned());
        forged.push(("child source", child_source));

        let mut payload = rex.clone();
        payload.operands[0].literal_value2 = Some("catalog".to_owned());
        forged.push(("child payload", payload));

        let mut trailing = rex.clone();
        trailing.source_text = Some("'store' || ''".to_owned());
        trailing.operands[0].source_text = Some("'store' || ''".to_owned());
        forged.push(("trailing source", trailing));

        let mut explicit = rex.clone();
        explicit.source_kind = Some("CAST".to_owned());
        explicit.source_operator = Some("CAST".to_owned());
        explicit.source_sql = Some("CAST('store' AS CHAR(7))".to_owned());
        explicit.source_text = Some("CAST('store' AS CHAR(7))".to_owned());
        explicit.source_node_id = Some(test_exact_span("CAST('store' AS CHAR(7))"));
        assert!(!implicit_exact_character_literal_cast_is_absent(&explicit));
        assert!(matches!(
            calcite_rex_ast(&explicit, &BTreeMap::new()).unwrap(),
            ScalarAst::TypeAnnotation { expr, ty }
                if ty == "CHAR(7)"
                    && matches!(expr.as_ref(), ScalarAst::Call { op: ScalarOp::Cast, .. })
        ));

        let mut target = rex.clone();
        target.ty = Some("VARCHAR".to_owned());
        target.full_type = Some("VARCHAR(7) NOT NULL".to_owned());
        target.text = Some("CAST('store'):VARCHAR(7) NOT NULL".to_owned());
        forged.push(("target family", target));

        let mut target_text = rex.clone();
        target_text.text = Some("CAST('store'):CHAR(8) NOT NULL".to_owned());
        forged.push(("target text", target_text));

        let mut generated_payload = rex.clone();
        generated_payload.literal_type_name = Some("CHAR".to_owned());
        forged.push(("parent literal payload", generated_payload));

        for (label, forged_rex) in forged {
            assert!(
                !implicit_exact_character_literal_cast_is_absent(&forged_rex),
                "forged {label} passed the exact literal-cast predicate"
            );
            assert_eq!(
                calcite_rex_source_provenance(&forged_rex)
                    .expect("forged carrier still has source provenance")
                    .operands
                    .len(),
                1,
                "forged {label} was incorrectly canonicalized as a bare leaf"
            );
            assert!(
                calcite_rex_ast(&forged_rex, &BTreeMap::new()).is_err(),
                "forged {label} unexpectedly stripped an implicit character CAST"
            );
        }
    }

    #[test]
    fn case_result_unknown_literal_cast_is_preserved_only_with_exact_parent_capability() {
        let mut cast = exact_implicit_character_literal_cast();
        cast.nullable = true;
        cast.full_type = Some("CHAR(7)".to_owned());
        cast.text = Some("CAST('store'):CHAR(7)".to_owned());

        let parent = with_exact_test_rex(
            serde_json::from_value(serde_json::json!({
                "kind": "CASE",
                "class": "RexCall",
                "text": "CASE(...):CHAR(7)",
                "type": "CHAR",
                "nullable": true,
                "fullType": "CHAR(7)",
                "precision": 7,
                "scale": i32::MIN,
                "charset": "ISO-8859-1",
                "typeCollation": CALCITE_1_42_STALE_TYPE_COLLATION,
                "sourceSql": "CASE WHEN flag THEN CAST(name AS CHAR(7)) ELSE 'store' END",
                "sourceKind": "CASE",
                "sourceOperator": "CASE",
                "operator": "CASE",
                "opKind": "CASE",
                "operands": []
            }))
            .unwrap(),
        );

        assert!(exact_preserved_case_result_character_literal_cast(
            &cast, &parent,
        ));
        assert!(!implicit_exact_character_literal_cast_is_absent(&cast));
        assert!(
            calcite_rex_ast_in_context(
                &cast,
                &BTreeMap::new(),
                RexContext::General,
                None,
                &BTreeSet::new(),
            )
            .is_err()
        );
        assert!(matches!(
            calcite_rex_ast_in_context(
                &cast,
                &BTreeMap::new(),
                RexContext::CaseResult,
                None,
                &BTreeSet::new(),
            )
            .unwrap(),
            ScalarAst::TypeAnnotation { expr, ty }
                if ty == "CHAR(7)"
                    && matches!(expr.as_ref(), ScalarAst::Call { op: ScalarOp::Cast, .. })
        ));

        let mut wrong_width = parent.clone();
        wrong_width.precision = Some(8);
        wrong_width.full_type = Some("CHAR(8)".to_owned());
        assert!(!exact_preserved_case_result_character_literal_cast(
            &cast,
            &wrong_width,
        ));
        let mut wrong_owner = parent;
        wrong_owner.source_kind = Some("COALESCE".to_owned());
        wrong_owner.source_operator = Some("COALESCE".to_owned());
        assert!(!exact_preserved_case_result_character_literal_cast(
            &cast,
            &wrong_owner,
        ));
    }

