    #[test]
    fn source_values_character_common_type_carrier_is_role_and_payload_closed() {
        let rex = exact_source_values_character_common_type_carrier();
        assert_eq!(
            exact_source_values_common_type_carrier(&rex).and_then(|child| child.text.as_deref()),
            Some("CAST('a'):CHAR(2) NOT NULL")
        );
        assert!(
            calcite_rex_ast(&rex, &BTreeMap::new()).is_err(),
            "the same carrier must not be stripped outside an exact source-VALUES parent"
        );
        let converted =
            convert_project_exprs(vec![rex.clone()], &BTreeMap::new(), None, true).unwrap();
        assert!(matches!(
            &converted[0].parsed,
            ScalarAst::TypeAnnotation { ty, expr }
                if ty == "CHAR(2)"
                    && matches!(expr.as_ref(), ScalarAst::Call { op: ScalarOp::Cast, .. })
        ));

        let mut forged = Vec::new();
        let mut source = rex.clone();
        source.source_text = Some("CAST('b' AS CHAR(2))".to_owned());
        forged.push(("root source", source));
        let mut child_source = rex.clone();
        child_source.operands[0].source_text = Some("CAST('b' AS CHAR(2))".to_owned());
        forged.push(("child source", child_source));
        let mut payload = rex.clone();
        payload.operands[0].operands[0].literal_value2 = Some("b".to_owned());
        forged.push(("literal payload", payload));
        let mut outer_typmod = rex.clone();
        outer_typmod.precision = Some(3);
        outer_typmod.full_type = Some("VARCHAR(3) NOT NULL".to_owned());
        forged.push(("outer typmod", outer_typmod));
        let mut child_typmod = rex.clone();
        child_typmod.operands[0].precision = Some(3);
        child_typmod.operands[0].full_type = Some("CHAR(3) NOT NULL".to_owned());
        forged.push(("explicit child typmod", child_typmod));
        let mut trailing = rex.clone();
        trailing.source_text = Some("CAST('a' AS CHAR(2)) || ''".to_owned());
        trailing.operands[0].source_text = trailing.source_text.clone();
        forged.push(("trailing source", trailing));

        for (label, forged_rex) in forged {
            assert!(
                exact_source_values_common_type_carrier(&forged_rex).is_none(),
                "forged {label} passed the source-VALUES carrier gate"
            );
        }
    }

