    #[test]
    fn values_padding_recovery_requires_exact_ascii_suffix_and_values_role() {
        let rex = exact_values_padded_character_literal();
        assert_eq!(
            exact_values_right_padded_character_literal(&rex).as_deref(),
            Some("'a'")
        );
        assert!(
            calcite_rex_literal_ast(&rex).is_err(),
            "ordinary scalar context must retain the source/payload mismatch rejection"
        );
        assert!(
            calcite_values_rex_scalar(rex.clone(), &BTreeMap::new(), false,).is_err(),
            "a LogicalValues call site without exact source-parent authority must reject"
        );
        assert!(matches!(
            calcite_values_rex_scalar(
                rex.clone(),
                &BTreeMap::new(),
                true,
            )
            .unwrap()
            .parsed,
            ScalarAst::Literal { raw } if raw == "'a'"
        ));

        let mut forged = Vec::new();
        let mut source = rex.clone();
        source.source_text = Some("'b'".to_owned());
        forged.push(("exact source", source));
        let mut payload = rex.clone();
        payload.literal_value2 = Some("ab".to_owned());
        forged.push(("non-space suffix", payload));
        let mut display = rex.clone();
        display.text = Some("'a'".to_owned());
        forged.push(("unpadded display", display));
        let mut typmod = rex.clone();
        typmod.precision = Some(3);
        typmod.full_type = Some("CHAR(3) NOT NULL".to_owned());
        forged.push(("typmod", typmod));
        let mut trailing = rex.clone();
        trailing.source_text = Some("'a' || ''".to_owned());
        forged.push(("trailing source", trailing));
        let mut truncation = rex.clone();
        truncation.source_text = Some("'aa'".to_owned());
        forged.push(("source truncation", truncation));

        for (label, forged_rex) in forged {
            assert!(
                exact_values_right_padded_character_literal(&forged_rex).is_none(),
                "forged {label} passed VALUES padding recovery"
            );
            assert!(
                calcite_values_rex_scalar(forged_rex, &BTreeMap::new(), true,).is_err(),
                "forged {label} reached a generic VALUES literal path"
            );
        }

        let mut actual_trailing_space = rex.clone();
        actual_trailing_space.source_sql = Some("'a '".to_owned());
        actual_trailing_space.source_node_id = Some("1:1-1:4".to_owned());
        actual_trailing_space.source_text = Some("'a '".to_owned());
        assert!(exact_values_right_padded_character_literal(&actual_trailing_space).is_none());
        assert!(matches!(
            calcite_values_rex_scalar(
                actual_trailing_space,
                &BTreeMap::new(),
                true,
            )
            .unwrap()
            .parsed,
            ScalarAst::Literal { raw } if raw == "'a '"
        ));

        let mut rendered_drift = rex;
        rendered_drift.source_sql = Some("'forged diagnostic text'".to_owned());
        assert_eq!(
            exact_values_right_padded_character_literal(&rendered_drift).as_deref(),
            Some("'a'"),
            "rendered sourceSql must not override exact sourceText"
        );
    }

