    #[test]
    fn sarg_wire_payloads_and_unstructured_sarg_literals_are_rejected() {
        let structured = serde_json::from_value::<CalciteRex>(serde_json::json!({
            "kind": "LITERAL",
            "class": "RexLiteral",
            "text": "Sarg[4]",
            "type": "INTEGER",
            "literalTypeName": "SARG",
            "sarg": {"text": "Sarg[4]"}
        }))
        .unwrap_err();
        assert!(structured.to_string().contains("unknown field `sarg`"));

        let unstructured: CalciteRex = with_exact_test_rex(
            serde_json::from_value(serde_json::json!({
                "kind": "LITERAL",
                "class": "RexLiteral",
                "text": "Sarg[4]",
                "type": "INTEGER",
                "nullable": false,
                "sourceSql": "x IN (4)",
                "sourceKind": "IN",
                "literalTypeName": "SARG"
            }))
            .unwrap(),
        );
        assert!(!calcite_literal_family_metadata_is_coherent(&unstructured));
        assert!(
            calcite_rex_literal_ast(&unstructured)
                .unwrap_err()
                .to_string()
                .contains("inconsistent family metadata")
        );
    }

